from author import begin, C, fixed, bounded, search, equal_pair, envelope, finish
begin("money")
fixed("Receipt field: uppercase USD, one space, exactly four ASCII digits, a point and exactly two literal zero digits. No other text.", "USD ", "0123456789", 4, ".00")
fixed("A prepaid card price is the euro symbol immediately followed by exactly three ASCII digits. No decimals or spaces.", "€", "0123456789", 3)
fixed("Validate a yen price label: three ASCII digits followed immediately by the literal suffix JPY, all uppercase.", "", "0123456789", 3, "JPY")
fixed("A cash drawer token is GBP: followed by exactly five ASCII digits; leading zeros are permitted.", "GBP:", "0123456789", 5)
C("A Swiss subtotal uses CHF, one ASCII space, one or more ASCII digits, a point, and exactly two fractional digits. Leading zeros are permitted; signs are not.", r"CHF [0-9]+\.[0-9]{2}", "CHF 0.00|CHF 1.05|CHF 10.20|CHF 999.99|CHF 000.01|CHF 5.50|CHF 20.00|CHF 12345.67", "CHF1.00|CHF 1,00|CHF 1.0|CHF 1.000|CHF -1.00|chf 1.00|CHF a.00", "Currency spelling, spacing and decimal precision are exact.")
bounded("Shipping surcharge in EUR: uppercase EUR and one space, then an integer 2 through 35 inclusive, no leading zeros, signs or fractional part.", "EUR ", 2, 35, r"(?:[2-9]|[12][0-9]|3[0-5])")
C("The kiosk accepts dollar prices from $0.00 through $99.99 using shortest integer spelling and exactly two cents digits, but cents must be 00, 25, 50 or 75.", r"\$(?:0|[1-9][0-9]?)\.(?:00|25|50|75)", "$0.00|$0.25|$1.50|$9.75|$10.00|$50.25|$99.50|$99.75", "$100.00|$01.00|$1.24|$1.26|$1.5|1.00|$-1.00", "The cents values are discrete alternatives, not an arbitrary range.")
C("French price entry: a canonical unsigned integer, comma, two ASCII cents digits, one nonbreaking space U+00A0 and euro symbol. No thousands separators or ordinary spaces.", r"(?:0|[1-9][0-9]*),[0-9]{2}\u00A0€", "0,00 €|1,25 €|9,99 €|10,00 €|123,45 €|999,99 €|2,05 €|1000,01 €", "1,00 €|01,00 €|1.00 €|1,0 €|1,000 €|-1,00 €|1,ab €", "A nonbreaking space is not interchangeable with a normal space.")
C("A UK expense amount is GBP followed by one space and either an amount with a positive canonical integer part and exactly two decimal places, or that same amount in parentheses for a refund. A zero integer part and leading zeros are not allowed.", r"GBP (?:[1-9][0-9]*\.[0-9]{2}|\([1-9][0-9]*\.[0-9]{2}\))", "GBP 1.00|GBP (1.00)|GBP 99.50|GBP (99.50)|GBP 10.01|GBP (10.01)|GBP 1234.00|GBP (1234.00)", "GBP 0.00|GBP (0.00)|GBP -1.00|GBP (1.00|GBP 1.00)|GBP 01.00|GBP 1.ab|GBP 1.0", "The parentheses must occur as a balanced alternative.")
bounded("A wallet load is the literal PLN followed by colon and an integer from 10 to 75 inclusive. No sign, leading zeros or spaces.", "PLN:", 10, 75, r"(?:[1-6][0-9]|7[0-5])")
search("Find a cent amount 0 to 99, in shortest ASCII decimal spelling, immediately between the lowercase text cents= and a semicolon. This is a contains search, with unrestricted surrounding text.", "cents=", r"(?:0|[1-9][0-9]?)", ["0","1","9","10","25","50","75","99"], ";", ["100","00","01","-1","1.0","x"])
C("Search payment notes for the exact currency token USD or EUR, bounded by start/end or a character other than an ASCII letter. Case matters and digits count as boundaries.", r"(?<![A-Za-z])(?:USD|EUR)(?![A-Za-z])", "USD|EUR|paid USD now|(EUR)|USD1|2EUR|USD/EUR|\nEUR\n", "usd|eur|USDA|xUSD|EURO|aEUR|US|E UR", "ASCII letter boundaries differ from generic word boundaries.", contains=True)
C("A donation amount starts with AUD and a space, then a canonical integer from 0 through 999 followed by a point and exactly two digits. The total amount must not be zero.", r"AUD (?!0\.00$)(?:0|[1-9][0-9]{0,2})\.[0-9]{2}", "AUD 0.01|AUD 0.99|AUD 1.00|AUD 9.25|AUD 99.99|AUD 999.99|AUD 100.00|AUD 10.10", "AUD 0.00|AUD 1000.00|AUD 01.00|AUD 1.0|AUD 1.000|AUD -1.00|AUD 1.ab", "The zero exclusion must not reject nonzero cents on a zero integer part.")
equal_pair("A price confirmation is USD: followed by two identical amounts separated by slash. Each amount is an integer 1 through 99 without leading zeros, a point, and exactly two ASCII cents digits; no spaces.", "USD:", "/", r"[1-9][0-9]?\.[0-9]{2}", ["1.00","9.99","10.25","99.99","20.50","5.75","40.01","88.88"])
C("A settlement record contains EUR or USD, colon, a canonical integer amount 1 through 99, slash, the exact same currency, colon, the exact same integer amount. No spaces or decimals.", r"(EUR|USD):([1-9][0-9]?)\/\1:\2", "EUR:1/EUR:1|USD:1/USD:1|EUR:99/EUR:99|USD:99/USD:99|EUR:10/EUR:10|USD:25/USD:25|EUR:50/EUR:50|USD:9/USD:9", "EUR:1/USD:1|EUR:1/EUR:2|EUR:01/EUR:01|EUR:0/EUR:0|EUR:100/EUR:100|eur:1/eur:1", "Currency and amount are two independent repeated fields.")
C("A currency display name consists of 2 to 12 Unicode letters, with at most one ASCII space joining two nonempty runs of letters. Count the space toward the length; combining marks and digits are not allowed.", r"(?=.{2,12}$)\p{L}+(?: \p{L}+)?", "Euro|Yen|Dollar|英镑|日本 円|Peso|Réais|abcdefghijkl", "A|abcdefghijklm|Euro  Yen| Euro|Euro |Euro2|éuro", "Length is measured in code points; marks are not letters.", "u")
envelope("A raw payment memo must be entirely wrapped in PAY{ and }PAY. The interior is 1 to 40 Unicode code points, may contain any characters including newlines, and must contain the lowercase substring paid.", "PAY{", "}PAY", "paid")
C("A two-line payout confirmation uses LF only. First line is currency= followed by EUR, USD, JPY, GBP, CHF, CAD, AUD or PLN; second is confirm= followed by the exact same currency. No final newline or extra whitespace.", r"currency=(EUR|USD|JPY|GBP|CHF|CAD|AUD|PLN)\nconfirm=\1", "currency=EUR\nconfirm=EUR|currency=USD\nconfirm=USD|currency=JPY\nconfirm=JPY|currency=GBP\nconfirm=GBP|currency=CHF\nconfirm=CHF|currency=CAD\nconfirm=CAD|currency=AUD\nconfirm=AUD|currency=PLN\nconfirm=PLN", "currency=EUR\nconfirm=USD|currency=eur\nconfirm=eur|currency=XXX\nconfirm=XXX|currency=EUR\r\nconfirm=EUR|currency=EUR confirm=EUR|currency=EUR\nconfirm=EUR ", "The currency must agree across lines.")
C("A cash batch is exactly three canonical positive amounts from 1 through 99, separated by commas. No two amounts may have identical decimal spellings. No currency symbol or spaces.", r"([1-9][0-9]?),(?!\1,)([1-9][0-9]?),(?!\1$)(?!\2$)[1-9][0-9]?", "1,2,3|99,98,97|1,10,99|10,1,20|5,50,55|12,34,56|90,9,19|2,22,23", "1,1,2|1,2,1|1,2,2|0,1,2|100,1,2|01,2,3|1, 2,3", "Uniqueness requires checking all three pairings.")
C("A quoted amount uses one matching pair of ASCII single or double quotes around EUR, a colon and a canonical integer 1 through 50. After the closing quote comes a space and the exact same integer, unquoted. Nothing else.", r"(['\"])EUR:([1-9]|[1-4][0-9]|50)\1 \2", "'EUR:1' 1|\"EUR:50\" 50|'EUR:9' 9|\"EUR:10\" 10|'EUR:20' 20|\"EUR:30\" 30|'EUR:40' 40|\"EUR:49\" 49", "'EUR:1\" 1|'EUR:1' 2|'EUR:0' 0|'EUR:51' 51|'EUR:01' 01|'EUR:1'  1", "Quote identity, numeric bounds and repeated amount all interact.")
finish()
